:root {
  /* Colors */
  --color-ember-signal: #f25533;
  --color-paper: #ffffff;
  --color-linen-surface: #f8f5f0;
  --color-sand-parchment: #f1ebe2;
  --color-mist-tile: #f7f7f8;
  --color-fog-chip: #f3f3f4;
  --color-carbon-panel: #1c1c1f;
  --color-jet-ink: #000000;
  --color-ink: #161618;
  --color-slate-caption: #656567;
  --color-pewter-meta: #6d6d70;
  --color-ink-hairline: #16161814;
  --color-quartz-border: #e8e8ea;

  /* Typography — Font Families */
  --font-stk-bureau-serif: "STKBureauSerif", "Newsreader Display", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-stk-bureau-sans: "STKBureauSans", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-geist-mono: "Geist Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.333;
  --tracking-small: 0px;
  --text-caption: 13px;
  --leading-caption: 1.4;
  --tracking-caption: -0.13px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.375;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.4;
  --tracking-body: -0.16px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.4;
  --tracking-body-lg: -0.18px;
  --text-subheading: 24px;
  --leading-subheading: 1.3;
  --tracking-subheading: -0.24px;
  --text-heading-sm: 36px;
  --leading-heading-sm: 1.15;
  --tracking-heading-sm: -0.9px;
  --text-heading: 44px;
  --leading-heading: 1.1;
  --tracking-heading: -1.32px;
  --text-display: 80px;
  --leading-display: 1;
  --tracking-display: -3.2px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-56: 56px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-96: 96px;
  --spacing-160: 160px;

  /* Layout */
  --layout-max-width: 1192px;
  --layout-section-gap: 96px;
  --layout-card-padding: 24px;
  --layout-element-gap: 12px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-lg-2: 7px;
  --radius-xl: 12px;
  --radius-3xl: 40px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-pills: 9999px;
  --radius-buttons: 9999px;
  --radius-tags: 9999px;
  --radius-avatars: 9999px;
  --radius-cards: 12px;
  --radius-images: 8px;
  --radius-inner-tiles: 8px;
  --radius-alert-banners: 7px;
  --radius-badges: 6px;
  --radius-small-elements: 4px;
  --radius-sections: 40px;

  /* Shadows */
  --shadow-subtle: 0 1px 6px 0 rgba(0, 0, 0, 0.03);
  --shadow-subtle-2: 0 0 0 1.5px #ffffff;
  --shadow-sm: 0 1px 2px 0 rgba(10, 20, 33, 0.03), 0 2px 6px 0 rgba(10, 20, 33, 0.05);
  --shadow-md: 0 8px 15px -3px rgba(22, 22, 24, 0.02), 0 4px 6px -2px rgba(22, 22, 24, 0.04);
  --shadow-md-2: 0 1px 2px 0 rgba(10, 20, 33, 0.1), 0 5px 14px 0 rgba(10, 20, 33, 0.1);
  --shadow-lg: 0 16px 25px -5px rgba(22, 22, 24, 0.06), 0 10px 10px -5px rgba(22, 22, 24, 0.04);
  --shadow-xl: 0 20px 50px -12px rgba(22, 22, 24, 0.16), 0 4px 6px 0 rgba(22, 22, 24, 0.04);
  --shadow-xl-2: 0 -12px 32px -12px rgba(0, 0, 0, 0.08);

  /* Surfaces */
  --surface-paper: #ffffff;
  --surface-linen-surface: #f8f5f0;
  --surface-sand-parchment: #f1ebe2;
  --surface-mist-tile: #f7f7f8;
  --surface-ember-signal: #f25533;
}

